import React, { useEffect, useState } from "react";

const API_URL =
  import.meta.env.VITE_API_URL || "http://localhost:5000/api/v1";

const TrackAppointment = () => {
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadToken = () => {
    try {
      const savedToken = localStorage.getItem(
        "queueless_hospital_token"
      );

      if (!savedToken) {
        setError("No appointment found.");
        setLoading(false);
        return;
      }

      const parsedToken = JSON.parse(savedToken);

      setToken(parsedToken);
      setLoading(false);
    } catch (err) {
      console.error("Track appointment error:", err);
      setError("Unable to load appointment.");
      setLoading(false);
    }
  };

  useEffect(() => {
    loadToken();
  }, []);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <p className="text-lg font-semibold">
          Loading appointment...
        </p>
      </div>
    );
  }

  if (error || !token) {
    return (
      <main className="min-h-screen bg-slate-50 px-6 py-16">
        <div className="mx-auto max-w-2xl rounded-2xl bg-white p-8 text-center shadow">
          <h1 className="text-2xl font-bold text-slate-900">
            No Appointment Found
          </h1>

          <p className="mt-3 text-slate-600">
            {error || "Please book an appointment first."}
          </p>

          <button
            type="button"
            onClick={() =>
              (window.location.href = "/hospitals")
            }
            className="mt-6 rounded-lg bg-blue-600 px-6 py-3 font-semibold text-white"
          >
            Book Appointment
          </button>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-50 px-6 py-16">
      <div className="mx-auto max-w-3xl">

        {/* HEADER */}

        <div className="mb-8">
          <h1 className="text-3xl font-bold text-slate-900">
            Track Appointment
          </h1>

          <p className="mt-2 text-slate-600">
            Track your hospital appointment and queue status.
          </p>
        </div>

        {/* TOKEN CARD */}

        <div className="rounded-2xl bg-white p-8 shadow">

          <div className="text-center">

            <p className="text-sm font-medium text-slate-500">
              Your Token Number
            </p>

            <h2 className="mt-2 text-5xl font-bold text-blue-600">
              {token.tokenNumber}
            </h2>

            <div className="mt-4 inline-flex rounded-full bg-yellow-100 px-4 py-2 text-sm font-semibold text-yellow-700">
              {token.status || "waiting"}
            </div>
          </div>

          {/* DETAILS */}

          <div className="mt-8 grid gap-4 md:grid-cols-2">

            <div className="rounded-xl bg-slate-50 p-4">
              <p className="text-sm text-slate-500">
                Patient
              </p>

              <p className="mt-1 font-semibold text-slate-900">
                {token.patientName}
              </p>
            </div>

            <div className="rounded-xl bg-slate-50 p-4">
              <p className="text-sm text-slate-500">
                Problem
              </p>

              <p className="mt-1 font-semibold text-slate-900">
                {token.problem}
              </p>
            </div>

            <div className="rounded-xl bg-slate-50 p-4">
              <p className="text-sm text-slate-500">
                Hospital
              </p>

              <p className="mt-1 font-semibold text-slate-900">
                {token.hospital?.name || "Hospital"}
              </p>
            </div>

            <div className="rounded-xl bg-slate-50 p-4">
              <p className="text-sm text-slate-500">
                Doctor
              </p>

              <p className="mt-1 font-semibold text-slate-900">
                {token.doctor?.name || "Doctor"}
              </p>
            </div>

          </div>

          {/* WAITING */}

          <div className="mt-6 rounded-xl border border-blue-100 bg-blue-50 p-5">

            <p className="text-sm text-blue-700">
              People Waiting
            </p>

            <p className="mt-1 text-3xl font-bold text-blue-900">
              {token.peopleWaiting ?? 0}
            </p>

            <p className="mt-3 text-sm text-blue-700">
              Estimated waiting time:{" "}
              <strong>
                {token.estimatedWaitingTime ?? 0} minutes
              </strong>
            </p>

            {token.expectedTime && (
              <p className="mt-2 text-sm text-blue-700">
                Expected consultation:{" "}
                <strong>{token.expectedTime}</strong>
              </p>
            )}

          </div>

          {/* BUTTONS */}

          <div className="mt-8 flex flex-wrap gap-3">

            <button
              type="button"
              onClick={loadToken}
              className="rounded-lg bg-blue-600 px-6 py-3 font-semibold text-white hover:bg-blue-700"
            >
              Refresh Status
            </button>

            <button
              type="button"
              onClick={() =>
                (window.location.href = "/hospitals")
              }
              className="rounded-lg border border-slate-300 bg-white px-6 py-3 font-semibold text-slate-700 hover:bg-slate-50"
            >
              Book Another Appointment
            </button>

          </div>

        </div>
      </div>
    </main>
  );
};

export default TrackAppointment;
